script:
# Copy Quotation number from Quotation to Sales Order
quotation_no = None

if doc.items:
    for item in doc.items:
        if item.quotation:
            q_doc = frappe.get_doc("Quotation", item.quotation)
            # Use custom field if present, else Quotation name
            quotation_no = getattr(q_doc, "so_quotation_no", q_doc.name)
            break

if quotation_no:
    # Count existing SOs for this quotation
    count = frappe.db.count("Sales Order", {"so_quotation_no": ["like", f"{quotation_no}%"]}) + 1
    doc.so_quotation_no = f"{quotation_no}-{count}"

if doc.items:
    for item in doc.items:
        if item.against_sales_order:
            so_doc = frappe.get_doc("Sales Order", item.against_sales_order)

            if so_doc.so_quotation_no:
                doc.so_quotation_no = so_doc.so_quotation_no
            else:
                doc.so_quotation_no = so_doc.name

            break

if doc.items:
    for item in doc.items:
        if item.sales_order:
            so_doc = frappe.get_doc("Sales Order", item.sales_order)

            if so_doc.so_quotation_no:
                doc.so_quotation_no = so_doc.so_quotation_no
            else:
                doc.so_quotation_no = so_doc.name

            break

        elif item.delivery_note:
            dn_doc = frappe.get_doc("Delivery Note", item.delivery_note)

            if dn_doc.so_quotation_no:
                doc.so_quotation_no = dn_doc.so_quotation_no
            else:
                doc.so_quotation_no = dn_doc.name

            break

frappe.throw("SCRIPT TRIGGERED")
def to_float(val):
    try:
        return float(val)
    except:
        return 0.0


def get_stock(item_code, warehouse):
    qty = frappe.db.get_value(
        "Bin",
        {
            "item_code": item_code,
            "warehouse": warehouse
        },
        "actual_qty"
    )
    return to_float(qty)


def create_transfer_from_picklist(doc):

    if not doc.items:
        return

    # Get unique Sales Orders
    sales_orders = []
    for d in doc.items:
        if d.sales_order and d.sales_order not in sales_orders:
            sales_orders.append(d.sales_order)

    if not sales_orders:
        return

    source_warehouse = doc.parent_warehouse

    for so_name in sales_orders:

        so = frappe.get_doc("Sales Order", so_name)
        target_warehouse = so.set_warehouse

        if not target_warehouse:
            frappe.throw("Sales Order " + so_name + " has no target warehouse")

        # 🔒 STRICT DUPLICATE CHECK
        existing = frappe.db.sql("""
            SELECT name FROM `tabStock Entry`
            WHERE docstatus < 2
            AND reference_sales_order = %s
            LIMIT 1
        """, (so_name,), as_dict=True)

        if existing:
            frappe.throw(
                "Stock already transferred for Sales Order " + so_name +
                " (Stock Entry: " + existing[0]["name"] + ")"
            )

        items_to_transfer = []

        for item in doc.items:

            if item.sales_order != so_name:
                continue

            if not item.item_code or not item.qty:
                continue

            required_qty = to_float(item.qty)

            available_qty = get_stock(item.item_code, target_warehouse)
            shortage = required_qty - available_qty

            if shortage <= 0:
                continue

            source_qty = get_stock(item.item_code, source_warehouse)

            if source_qty <= 0:
                frappe.throw(
                    "No stock in " + source_warehouse +
                    " for item " + item.item_code
                )

            transfer_qty = shortage if shortage < source_qty else source_qty

            items_to_transfer.append({
                "item_code": item.item_code,
                "qty": transfer_qty,
                "uom": item.uom,
                "s_warehouse": source_warehouse,
                "t_warehouse": target_warehouse
            })

        if not items_to_transfer:
            continue

        # Create Stock Entry
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.company = so.company
        se.reference_sales_order = so_name

        for d in items_to_transfer:
            se.append("items", d)

        se.insert()
        se.submit()


# Required entry point
create_transfer_from_picklist(doc)

for item in doc.items:
    if item.quotation_item:
        qi = frappe.get_doc("Quotation Item", item.quotation_item)
        item.custom_discount = qi.custom_discounted

# Sample Issuance - Before Save
# Purpose:
# - Sync sample_status with workflow_state before issuing
# - Compute child row status
# - After submit, sample_status becomes return/stock status

if not doc.issue_date:
    doc.issue_date = frappe.utils.today()

workflow_state = doc.workflow_state or ""

if not doc.sample_status:
    if workflow_state:
        doc.sample_status = workflow_state
    else:
        doc.sample_status = "Draft"

if not doc.items:
    frappe.throw("Please add at least one sample item.")

total_good = 0
total_damaged = 0
total_lost = 0
total_still_out = 0

for row in doc.items:
    if not row.item_code:
        frappe.throw("Item Code is required in the sample items table.")

    if not row.qty_issued or row.qty_issued <= 0:
        frappe.throw("Qty Issued must be greater than zero for item " + row.item_code)

    if not row.uom:
        item_uom = frappe.db.get_value("Item", row.item_code, "stock_uom")
        if item_uom:
            row.uom = item_uom

    if not row.item_name:
        item_name = frappe.db.get_value("Item", row.item_code, "item_name")
        if item_name:
            row.item_name = item_name

    qty_issued = row.qty_issued or 0
    qty_good = row.qty_returned_good or 0
    qty_damaged = row.qty_damaged or 0
    qty_lost = row.qty_lost or 0

    total_accounted = qty_good + qty_damaged + qty_lost

    if total_accounted > qty_issued:
        frappe.throw(
            "For item " + row.item_code + ", Returned Good + Damaged + Lost quantity cannot exceed Qty Issued."
        )

    row.qty_still_out = qty_issued - total_accounted

    if row.qty_still_out == qty_issued:
        row.return_status = "Pending"
    elif row.qty_still_out > 0:
        row.return_status = "Partially Returned"
    elif qty_lost > 0:
        row.return_status = "Lost / Not Returned"
    elif qty_damaged > 0:
        row.return_status = "Damaged"
    else:
        row.return_status = "Returned"

    total_good = total_good + qty_good
    total_damaged = total_damaged + qty_damaged
    total_lost = total_lost + qty_lost
    total_still_out = total_still_out + row.qty_still_out

# Before submit: sample_status follows workflow_state
if doc.docstatus == 0:
    if workflow_state:
        doc.sample_status = workflow_state
    else:
        doc.sample_status = "Draft"

# After submit: sample_status follows return/stock condition
if doc.docstatus == 1:
    if total_lost > 0:
        doc.sample_status = "With Unreturned Items"
    elif total_damaged > 0:
        doc.sample_status = "With Damaged Items"
    elif total_still_out == 0:
        doc.sample_status = "Returned"
    elif total_good > 0 or total_damaged > 0 or total_lost > 0:
        doc.sample_status = "Partially Returned"
    else:
        doc.sample_status = "Issued"

# Cancelled document
if doc.docstatus == 2:
    doc.sample_status = "Cancelled"

# ============================================================
# SALES ORDER - BEFORE VALIDATE
# ============================================================
#
# PRESERVED LOGIC:
# 1. Copy Quotation Item pricing and discount fields into
#    Sales Order Item.
#
# ADDED / UPDATED LOGIC:
# 2. Copy Quotation.custom_branch to Sales Order.branch.
# 3. Copy the fulfillment mode from the source Quotation.
# 4. Default branch from User.custom_default_branch when needed.
# 5. Ordinary fulfillment uses:
#       Branch.custom_default_branch_warehouse
# 6. Central fulfillment uses:
#       Branch.custom_fulfillment_warehouse
# 7. Both modes use:
#       Branch.custom_selling_cost_center
# 8. Validate warehouse and Cost Center company.
# 9. Apply warehouse and Cost Center to every item.
#
# SALES ORDER FIELDS:
# branch
# custom_central_fulfillment
# custom_fulfillment_warehouse
# custom_fulfillment_status
#
# QUOTATION FIELD:
# custom_branch
#
# USER FIELD:
# custom_default_branch
#
# BRANCH FIELDS:
# custom_default_branch_warehouse
# custom_fulfillment_warehouse
# custom_selling_cost_center
# custom_allow_central_fulfillment
# custom_warehouse_company
# ============================================================


# ============================================================
# PART 1: PRESERVE QUOTATION PRICING VALUES
# ============================================================

source_quotations = []

for item in doc.items:

    quotation_item_name = ""

    if item.get("prevdoc_detail_docname"):
        quotation_item_name = item.get(
            "prevdoc_detail_docname"
        )

    if (
        not quotation_item_name and
        item.get("quotation_item")
    ):
        quotation_item_name = item.get(
            "quotation_item"
        )

    if (
        not quotation_item_name and
        item.get("custom_quotation_item")
    ):
        quotation_item_name = item.get(
            "custom_quotation_item"
        )

    if quotation_item_name:

        quotation_values = frappe.db.get_value(
            "Quotation Item",
            quotation_item_name,
            [
                "parent",
                "custom_base_rate_before_markup",
                "custom_branch_markup_percentage",
                "custom_marked_up_rate",
                "custom_discounted"
            ],
            as_dict=1
        )

        if quotation_values:

            item.custom_base_rate_before_markup = (
                quotation_values.custom_base_rate_before_markup or 0
            )

            item.custom_branch_markup_percentage = (
                quotation_values.custom_branch_markup_percentage or 0
            )

            item.custom_marked_up_rate = (
                quotation_values.custom_marked_up_rate or 0
            )

            # Quotation Item.custom_discounted
            #     ↓
            # Sales Order Item.custom_discount
            #
            # This is the final TOTAL amount for the row.
            item.custom_discount = (
                quotation_values.custom_discounted or 0
            )

            source_quotation = (
                quotation_values.parent
            )

            if (
                source_quotation and
                source_quotation not in source_quotations
            ):
                source_quotations.append(
                    source_quotation
                )


# ============================================================
# PART 2: GET SOURCE QUOTATIONS FROM ITEM REFERENCES
# ============================================================

for item in doc.items:

    possible_quotation = ""

    if item.get("prevdoc_docname"):
        possible_quotation = item.get(
            "prevdoc_docname"
        )

    if (
        not possible_quotation and
        item.get("quotation")
    ):
        possible_quotation = item.get(
            "quotation"
        )

    if (
        possible_quotation and
        possible_quotation not in source_quotations
    ):
        source_quotations.append(
            possible_quotation
        )


# ============================================================
# PART 3: COPY BRANCH AND FULFILLMENT MODE FROM QUOTATION
# ============================================================

quotation_branch = ""
quotation_central_fulfillment = None

for source_quotation in source_quotations:

    quotation_header = frappe.db.get_value(
        "Quotation",
        source_quotation,
        [
            "company",
            "custom_branch",
            "custom_central_fulfillment"
        ],
        as_dict=1
    )

    if not quotation_header:
        frappe.throw(
            "Source Quotation {0} could not be found.".format(
                source_quotation
            )
        )

    if quotation_header.company != doc.company:
        frappe.throw(
            "Quotation {0} belongs to company {1}, but this "
            "Sales Order belongs to company {2}.".format(
                source_quotation,
                quotation_header.company,
                doc.company
            )
        )

    if quotation_header.custom_branch:

        if not quotation_branch:
            quotation_branch = (
                quotation_header.custom_branch
            )

        elif (
            quotation_branch !=
            quotation_header.custom_branch
        ):
            frappe.throw(
                "This Sales Order contains Quotation Items from "
                "different branches."
            )

    current_quotation_mode = (
        quotation_header.custom_central_fulfillment or 0
    )

    if quotation_central_fulfillment is None:
        quotation_central_fulfillment = (
            current_quotation_mode
        )

    elif (
        quotation_central_fulfillment !=
        current_quotation_mode
    ):
        frappe.throw(
            "This Sales Order contains Quotations with different "
            "fulfillment modes."
        )


# Copy Quotation branch when Sales Order branch is empty.
if quotation_branch and not doc.get("branch"):
    doc.branch = quotation_branch


# Prevent changing the branch away from the source Quotation.
if (
    quotation_branch and
    doc.get("branch") and
    doc.branch != quotation_branch
):
    frappe.throw(
        "Sales Order Branch must match the source Quotation Branch. "
        "Expected branch: {0}. Current branch: {1}.".format(
            quotation_branch,
            doc.branch
        )
    )


# Copy fulfillment mode from Quotation.
if quotation_central_fulfillment is not None:
    doc.custom_central_fulfillment = (
        quotation_central_fulfillment
    )


# ============================================================
# PART 4: DEFAULT BRANCH FROM LOGGED-IN USER
# ============================================================

if not doc.get("branch"):

    current_user = frappe.session.user

    if (
        current_user and
        current_user != "Guest"
    ):
        user_default_branch = frappe.db.get_value(
            "User",
            current_user,
            "custom_default_branch"
        )

        if user_default_branch:
            doc.branch = user_default_branch


if not doc.get("branch"):
    frappe.throw(
        "Branch is required. Configure Default Branch on the User "
        "record, select a Branch, or create the Sales Order from "
        "a Quotation that has a Branch."
    )


# ============================================================
# PART 5: READ BRANCH FULFILLMENT SETTINGS
# ============================================================

branch_settings = frappe.db.get_value(
    "Branch",
    doc.branch,
    [
        "custom_default_branch_warehouse",
        "custom_fulfillment_warehouse",
        "custom_selling_cost_center",
        "custom_allow_central_fulfillment",
        "custom_warehouse_company"
    ],
    as_dict=1
)

if not branch_settings:
    frappe.throw(
        "Branch {0} could not be found.".format(
            doc.branch
        )
    )


default_branch_warehouse = (
    branch_settings.custom_default_branch_warehouse
)

central_fulfillment_warehouse = (
    branch_settings.custom_fulfillment_warehouse
)

branch_cost_center = (
    branch_settings.custom_selling_cost_center
)

allow_central_fulfillment = (
    branch_settings.custom_allow_central_fulfillment or 0
)

configured_warehouse_company = (
    branch_settings.custom_warehouse_company
)

use_central_fulfillment = (
    doc.get("custom_central_fulfillment") or 0
)


# ============================================================
# PART 6: DETERMINE THE EXPECTED WAREHOUSE
# ============================================================

selected_warehouse = ""

if use_central_fulfillment:

    if not allow_central_fulfillment:
        frappe.throw(
            "Central fulfillment is not enabled for branch {0}.".format(
                doc.branch
            )
        )

    if not central_fulfillment_warehouse:
        frappe.throw(
            "Main Fulfillment Warehouse is not configured for "
            "branch {0}.".format(
                doc.branch
            )
        )

    selected_warehouse = (
        central_fulfillment_warehouse
    )

else:

    if not default_branch_warehouse:
        frappe.throw(
            "Default Branch Warehouse is not configured for "
            "branch {0}.".format(
                doc.branch
            )
        )

    selected_warehouse = (
        default_branch_warehouse
    )


# ============================================================
# PART 7: VALIDATE BRANCH COST CENTER
# ============================================================

if not branch_cost_center:
    frappe.throw(
        "Selling Cost Center is not configured for branch {0}.".format(
            doc.branch
        )
    )

cost_center_values = frappe.db.get_value(
    "Cost Center",
    branch_cost_center,
    [
        "name",
        "company"
    ],
    as_dict=1
)

if not cost_center_values:
    frappe.throw(
        "Selling Cost Center {0} could not be found.".format(
            branch_cost_center
        )
    )

if cost_center_values.company != doc.company:
    frappe.throw(
        "Selling Cost Center {0} belongs to company {1}, "
        "but this Sales Order belongs to company {2}.".format(
            branch_cost_center,
            cost_center_values.company,
            doc.company
        )
    )


# ============================================================
# PART 8: VALIDATE SELECTED WAREHOUSE
# ============================================================

warehouse_values = frappe.db.get_value(
    "Warehouse",
    selected_warehouse,
    [
        "name",
        "company",
        "is_group"
    ],
    as_dict=1
)

if not warehouse_values:
    frappe.throw(
        "Warehouse {0} could not be found.".format(
            selected_warehouse
        )
    )

if warehouse_values.company != doc.company:
    frappe.throw(
        "Warehouse {0} belongs to company {1}, "
        "but this Sales Order belongs to company {2}.".format(
            selected_warehouse,
            warehouse_values.company,
            doc.company
        )
    )

if (
    configured_warehouse_company and
    configured_warehouse_company != doc.company
):
    frappe.throw(
        "Branch {0} is configured to use warehouses under company "
        "{1}, but this Sales Order belongs to company {2}.".format(
            doc.branch,
            configured_warehouse_company,
            doc.company
        )
    )


# Ordinary branch warehouse must be an actual warehouse.
# Central fulfillment may initially use a group warehouse because
# Pick List will select the actual child/bin warehouse.
if (
    not use_central_fulfillment and
    warehouse_values.is_group
):
    frappe.throw(
        "Default Branch Warehouse {0} is a group warehouse. "
        "Configure an actual non-group warehouse for ordinary "
        "branch transactions.".format(
            selected_warehouse
        )
    )


# ============================================================
# PART 9: APPLY HEADER FULFILLMENT VALUES
# ============================================================

doc.custom_fulfillment_warehouse = (
    selected_warehouse
)

if doc.meta.has_field("set_warehouse"):
    doc.set_warehouse = selected_warehouse


if (
    doc.meta.has_field(
        "custom_fulfillment_status"
    ) and
    not doc.get(
        "custom_fulfillment_status"
    )
):
    doc.custom_fulfillment_status = (
        "Awaiting Approval"
    )


# ============================================================
# PART 10: APPLY ITEM WAREHOUSE AND COST CENTER
# ============================================================

for item in doc.items:

    item.warehouse = selected_warehouse
    item.cost_center = branch_cost_center

# ============================================================
# DR PAPER SERIAL LOG - AFTER INSERT
# ============================================================
# Purpose:
# Move DR Paper Batch current_serial to the next unused serial.
# ============================================================

if not doc.get("batch"):
    frappe.throw("DR Paper Batch is required.")

batch = frappe.get_doc("DR Paper Batch", doc.batch)

current_serial = int(batch.current_serial or batch.start_serial)
logged_serial = int(doc.dr_paper_serial)

if logged_serial >= current_serial:
    next_serial = current_serial

    while next_serial <= int(batch.end_serial):
        existing = frappe.db.exists(
            "DR Paper Serial Log",
            {
                "branch": batch.branch,
                "dr_paper_serial": str(next_serial)
            }
        )

        if not existing:
            break

        next_serial = next_serial + 1

    if next_serial > int(batch.end_serial):
        batch.db_set("current_serial", next_serial)
        batch.db_set("status", "Exhausted")
    else:
        batch.db_set("current_serial", next_serial)

# Auto-fill warehouse defaults based on company
# Safe fallback if Client Script did not fill the fields

company = ""

if doc.company:
    company = doc.company

if not company:
    employee_company = frappe.db.get_value(
        "Employee",
        {
            "user_id": frappe.session.user,
            "status": "Active"
        },
        "company"
    )

    if employee_company:
        company = employee_company
        doc.company = company

if not company:
    default_company = frappe.db.get_single_value("Global Defaults", "default_company")

    if default_company:
        company = default_company
        doc.company = company

if company:
    if not doc.source_warehouse:
        source_warehouse = frappe.db.get_value(
            "Company",
            company,
            "custom_default_sample_source_warehouse"
        )

        if source_warehouse:
            doc.source_warehouse = source_warehouse

    if not doc.sample_issued_warehouse:
        sample_issued_warehouse = frappe.db.get_value(
            "Company",
            company,
            "custom_default_sample_issued_warehouse"
        )

        if sample_issued_warehouse:
            doc.sample_issued_warehouse = sample_issued_warehouse

    if not doc.return_warehouse:
        return_warehouse = frappe.db.get_value(
            "Company",
            company,
            "custom_default_sample_return_warehouse"
        )

        if return_warehouse:
            doc.return_warehouse = return_warehouse

    if not doc.damaged_warehouse:
        damaged_warehouse = frappe.db.get_value(
            "Company",
            company,
            "custom_default_sample_damaged_warehouse"
        )

        if damaged_warehouse:
            doc.damaged_warehouse = damaged_warehouse

    if not doc.lost_warehouse:
        lost_warehouse = frappe.db.get_value(
            "Company",
            company,
            "custom_default_sample_lost_warehouse"
        )

        if lost_warehouse:
            doc.lost_warehouse = lost_warehouse

# ============================================================
# SALES ORDER - BEFORE SUBMIT
# FINAL BRANCH AND FULFILLMENT VALIDATION
# ============================================================
#
# Supports:
#
# 1. Ordinary branch fulfillment
#    Warehouse = Branch.custom_default_branch_warehouse
#
# 2. Central fulfillment
#    Warehouse = Branch.custom_fulfillment_warehouse
#
# In both cases:
#    Cost Center = Branch.custom_selling_cost_center
#
# Event:
#    Before Submit
# ============================================================


# ============================================================
# PART 1: VALIDATE BRANCH
# ============================================================

if not doc.branch:
    frappe.throw(
        "Branch is required before submitting the Sales Order."
    )


# ============================================================
# PART 2: LOAD BRANCH SETTINGS
# ============================================================

branch_settings = frappe.db.get_value(
    "Branch",
    doc.branch,
    [
        "custom_default_branch_warehouse",
        "custom_fulfillment_warehouse",
        "custom_selling_cost_center",
        "custom_allow_central_fulfillment",
        "custom_warehouse_company"
    ],
    as_dict=1
)

if not branch_settings:
    frappe.throw(
        "Branch {0} could not be found.".format(
            doc.branch
        )
    )


default_branch_warehouse = (
    branch_settings.custom_default_branch_warehouse
)

central_fulfillment_warehouse = (
    branch_settings.custom_fulfillment_warehouse
)

branch_cost_center = (
    branch_settings.custom_selling_cost_center
)

allow_central_fulfillment = (
    branch_settings.custom_allow_central_fulfillment or 0
)

configured_warehouse_company = (
    branch_settings.custom_warehouse_company
)

use_central_fulfillment = (
    doc.custom_central_fulfillment or 0
)


# ============================================================
# PART 3: DETERMINE EXPECTED WAREHOUSE
# ============================================================

expected_warehouse = ""

if use_central_fulfillment:

    if not allow_central_fulfillment:
        frappe.throw(
            "Central fulfillment is not enabled for branch {0}.".format(
                doc.branch
            )
        )

    if not central_fulfillment_warehouse:
        frappe.throw(
            "Main Fulfillment Warehouse is not configured for "
            "branch {0}.".format(
                doc.branch
            )
        )

    expected_warehouse = (
        central_fulfillment_warehouse
    )

else:

    if not default_branch_warehouse:
        frappe.throw(
            "Default Branch Warehouse is not configured for "
            "branch {0}.".format(
                doc.branch
            )
        )

    expected_warehouse = (
        default_branch_warehouse
    )


# ============================================================
# PART 4: VALIDATE COST CENTER
# ============================================================

if not branch_cost_center:
    frappe.throw(
        "Selling Cost Center is not configured for branch {0}.".format(
            doc.branch
        )
    )

cost_center_company = frappe.db.get_value(
    "Cost Center",
    branch_cost_center,
    "company"
)

if not cost_center_company:
    frappe.throw(
        "Selling Cost Center {0} could not be found.".format(
            branch_cost_center
        )
    )

if cost_center_company != doc.company:
    frappe.throw(
        "Selling Cost Center {0} belongs to company {1}, "
        "but this Sales Order belongs to company {2}.".format(
            branch_cost_center,
            cost_center_company,
            doc.company
        )
    )


# ============================================================
# PART 5: VALIDATE WAREHOUSE
# ============================================================

warehouse_values = frappe.db.get_value(
    "Warehouse",
    expected_warehouse,
    [
        "name",
        "company",
        "is_group"
    ],
    as_dict=1
)

if not warehouse_values:
    frappe.throw(
        "Warehouse {0} could not be found.".format(
            expected_warehouse
        )
    )

if warehouse_values.company != doc.company:
    frappe.throw(
        "Warehouse {0} belongs to company {1}, "
        "but this Sales Order belongs to company {2}.".format(
            expected_warehouse,
            warehouse_values.company,
            doc.company
        )
    )

if (
    configured_warehouse_company and
    configured_warehouse_company != doc.company
):
    frappe.throw(
        "Branch {0} is configured to use warehouses under "
        "company {1}, but this Sales Order belongs to "
        "company {2}.".format(
            doc.branch,
            configured_warehouse_company,
            doc.company
        )
    )

# Ordinary branch fulfillment must use an actual warehouse.
# Central fulfillment may use a group warehouse because
# the Pick List will later select the actual bin warehouse.
if (
    not use_central_fulfillment and
    warehouse_values.is_group
):
    frappe.throw(
        "Default Branch Warehouse {0} is a group warehouse. "
        "Configure an actual non-group warehouse for ordinary "
        "branch fulfillment.".format(
            expected_warehouse
        )
    )


# ============================================================
# PART 6: VALIDATE HEADER WAREHOUSE VALUES
# ============================================================

if not doc.custom_fulfillment_warehouse:
    frappe.throw(
        "Order Fulfillment Warehouse is required."
    )

if (
    doc.custom_fulfillment_warehouse !=
    expected_warehouse
):
    frappe.throw(
        "The Sales Order fulfillment warehouse must be {0} "
        "for branch {1}. Current value: {2}.".format(
            expected_warehouse,
            doc.branch,
            doc.custom_fulfillment_warehouse
        )
    )

if (
    doc.meta.has_field("set_warehouse") and
    doc.set_warehouse != expected_warehouse
):
    frappe.throw(
        "Set Warehouse must be {0} for this Sales Order.".format(
            expected_warehouse
        )
    )


# ============================================================
# PART 7: VALIDATE ITEM DIMENSIONS
# ============================================================

if not doc.items:
    frappe.throw(
        "Add at least one item before submitting the Sales Order."
    )

for item in doc.items:

    if item.cost_center != branch_cost_center:
        frappe.throw(
            "Row {0}: Cost Center must be {1} for selling "
            "branch {2}.".format(
                item.idx,
                branch_cost_center,
                doc.branch
            )
        )

    if item.warehouse != expected_warehouse:
        if use_central_fulfillment:
            frappe.throw(
                "Row {0}: Warehouse must initially be {1}. "
                "The Pick List may later select an actual child "
                "or bin warehouse.".format(
                    item.idx,
                    expected_warehouse
                )
            )

        frappe.throw(
            "Row {0}: Warehouse must be the branch warehouse "
            "{1}.".format(
                item.idx,
                expected_warehouse
            )
        )


# ============================================================
# PART 8: SET FULFILLMENT STATUS
# ============================================================

if doc.meta.has_field(
    "custom_fulfillment_status"
):
    doc.custom_fulfillment_status = (
        "Ready for Warehouse"
    )

# ============================================================
# GET CURRENT USER BRANCH FROM USER PERMISSION
# ============================================================

current_user = frappe.session.user
user_branch = ""

if current_user and current_user != "Guest":

    branch_permissions = frappe.get_all(
        "User Permission",
        filters={
            "user": current_user,
            "allow": "Branch",
            "is_default": 1
        },
        fields=[
            "for_value"
        ],
        order_by="creation asc",
        limit=1
    )

    # If no Branch permission is marked as default,
    # use the first available Branch permission.
    if not branch_permissions:

        branch_permissions = frappe.get_all(
            "User Permission",
            filters={
                "user": current_user,
                "allow": "Branch"
            },
            fields=[
                "for_value"
            ],
            order_by="creation asc",
            limit=1
        )

    if branch_permissions:
        user_branch = (
            branch_permissions[0].for_value or ""
        )

frappe.response["message"] = user_branch

# ============================================================
# DELIVERY NOTE - HIERARCHICAL VISIBILITY
# ERPNext / Frappe v16
#
# PURPOSE
# ------------------------------------------------------------
# Restrict Delivery Note visibility for users who belong to
# Sales Access Hierarchy.
#
# Visibility is based on:
#
# 1. Self + hierarchy descendants
# 2. Primary / Allowed Company
# 3. Primary / Allowed Branch when configured
# 4. Primary / Allowed Sales Team when configured
#
# Users outside Sales Access Hierarchy:
# Normal ERPNext permissions remain unchanged.
#
# This allows Warehouse / Stock / Accounts users to continue
# operating Delivery Notes normally.
#
# No imports.
# No .format().
# ============================================================


current_user = user


# ============================================================
# 1. ADMINISTRATOR
# ============================================================

if current_user == "Administrator":

    conditions = ""


else:

    # ========================================================
    # 2. GET CURRENT USER HIERARCHY
    # ========================================================

    hierarchy = frappe.db.get_value(
        "Sales Access Hierarchy",
        {
            "user": current_user,
            "active": 1
        },
        [
            "name",
            "user",
            "position",
            "company",
            "branch",
            "sales_team_group"
        ],
        as_dict=1
    )


    # ========================================================
    # 3. NON-HIERARCHY USER
    # ========================================================

    has_company_scope = False
    has_branch_scope = False
    has_team_scope = False

    if hierarchy:
        has_company_scope = bool(
            hierarchy.company
            or frappe.db.exists("Sales Hierarchy Company Access", {"parent": hierarchy.name, "company": ["!=", ""]})
        )
        has_branch_scope = bool(
            hierarchy.branch
            or frappe.db.exists("Sales Hierarchy Branch Access", {"parent": hierarchy.name, "branch": ["!=", ""]})
        )
        has_team_scope = bool(
            hierarchy.sales_team_group
            or frappe.db.exists("Sales Hierarchy Team Access", {"parent": hierarchy.name, "sales_team_group": ["!=", ""]})
        )

    if not hierarchy:

        conditions = ""


    elif hierarchy.position == "Business Owner":

        # Company-wide access: no Branch, Team, or user restriction.
        owner_companies = []

        if hierarchy.company:

            owner_companies.append(hierarchy.company)

        owner_company_rows = frappe.get_all(
            "Sales Hierarchy Company Access",
            filters={"parent": hierarchy.name, "parenttype": "Sales Access Hierarchy", "parentfield": "allowed_companies"},
            fields=["company"]
        )

        for owner_company_row in owner_company_rows:

            if owner_company_row.company and owner_company_row.company not in owner_companies:

                owner_companies.append(owner_company_row.company)

        owner_company_values = ""

        for owner_company in owner_companies:

            escaped_owner_company = frappe.db.escape(owner_company)

            if owner_company_values:

                owner_company_values = owner_company_values + ", "

            owner_company_values = owner_company_values + escaped_owner_company

        if owner_company_values:

            conditions = "`tabDelivery Note`.`company` IN (" + owner_company_values + ")"

        else:

            conditions = "1 = 0"

    elif not has_company_scope or not has_branch_scope or not has_team_scope:

        conditions = "1 = 0"


    else:

        # ====================================================
        # 4. BUILD SELF + DESCENDANT USERS
        # ====================================================

        allowed_users = []


        if hierarchy.user:

            allowed_users.append(
                hierarchy.user
            )


        current_level = [
            hierarchy.name
        ]


        checked_records = []

        depth = 0


        while current_level and depth < 50:

            next_level = []


            children = frappe.get_all(
                "Sales Access Hierarchy",
                filters={
                    "reports_to": ["in", current_level],
                    "active": 1
                },
                fields=[
                    "name",
                    "user"
                ]
            )


            for child in children:

                if child.name not in checked_records:

                    checked_records.append(
                        child.name
                    )


                    if child.user:

                        if child.user not in allowed_users:

                            allowed_users.append(
                                child.user
                            )


                    if child.name not in next_level:

                        next_level.append(
                            child.name
                        )


            current_level = next_level

            depth = depth + 1


        # ====================================================
        # 5. CONDITION PARTS
        # ====================================================

        condition_parts = []


        # ====================================================
        # 6. SALES USER
        # ====================================================

        # Team Leaders and Supervisors aggregate the complete scoped
        # Sales Team. Sales Representatives and other scoped positions
        # remain restricted to self plus explicit hierarchy descendants.
        if hierarchy.position in ["Team Leader", "Supervisor"]:

            pass

        elif allowed_users:

            users_sql_values = ""


            for allowed_user in allowed_users:

                escaped_user = frappe.db.escape(
                    allowed_user
                )


                if users_sql_values:

                    users_sql_values = (
                        users_sql_values
                        + ", "
                    )


                users_sql_values = (
                    users_sql_values
                    + escaped_user
                )


            condition_parts.append(
                "`tabDelivery Note`.`custom_sales_user` IN ("
                + users_sql_values
                + ")"
            )


        else:

            condition_parts.append(
                "1 = 0"
            )


        # ====================================================
        # 7. COMPANY
        # ====================================================

        allowed_companies = []


        if hierarchy.company:

            allowed_companies.append(
                hierarchy.company
            )


        company_rows = frappe.get_all(
            "Sales Hierarchy Company Access",
            filters={
                "parent": hierarchy.name,
                "parenttype": "Sales Access Hierarchy",
                "parentfield": "allowed_companies"
            },
            fields=[
                "company"
            ]
        )


        for company_row in company_rows:

            if company_row.company:

                if company_row.company not in allowed_companies:

                    allowed_companies.append(
                        company_row.company
                    )


        if allowed_companies:

            company_sql_values = ""


            for allowed_company in allowed_companies:

                escaped_company = frappe.db.escape(
                    allowed_company
                )


                if company_sql_values:

                    company_sql_values = (
                        company_sql_values
                        + ", "
                    )


                company_sql_values = (
                    company_sql_values
                    + escaped_company
                )


            condition_parts.append(
                "`tabDelivery Note`.`company` IN ("
                + company_sql_values
                + ")"
            )


        # ====================================================
        # 8. BRANCH
        # ====================================================

        allowed_branches = []


        if hierarchy.branch:

            allowed_branches.append(
                hierarchy.branch
            )


        branch_rows = frappe.get_all(
            "Sales Hierarchy Branch Access",
            filters={
                "parent": hierarchy.name,
                "parenttype": "Sales Access Hierarchy",
                "parentfield": "allowed_branches"
            },
            fields=[
                "branch"
            ]
        )


        for branch_row in branch_rows:

            if branch_row.branch:

                if branch_row.branch not in allowed_branches:

                    allowed_branches.append(
                        branch_row.branch
                    )


        if allowed_branches:

            branch_sql_values = ""


            for allowed_branch in allowed_branches:

                escaped_branch = frappe.db.escape(
                    allowed_branch
                )


                if branch_sql_values:

                    branch_sql_values = (
                        branch_sql_values
                        + ", "
                    )


                branch_sql_values = (
                    branch_sql_values
                    + escaped_branch
                )


            condition_parts.append(
                "`tabDelivery Note`.`branch` IN ("
                + branch_sql_values
                + ")"
            )


        # ====================================================
        # 9. SALES TEAM
        # ====================================================

        allowed_teams = []


        if hierarchy.sales_team_group:

            allowed_teams.append(
                hierarchy.sales_team_group
            )


        team_rows = frappe.get_all(
            "Sales Hierarchy Team Access",
            filters={
                "parent": hierarchy.name,
                "parenttype": "Sales Access Hierarchy",
                "parentfield": "allowed_sales_teams"
            },
            fields=[
                "sales_team_group"
            ]
        )


        for team_row in team_rows:

            if team_row.sales_team_group:

                if team_row.sales_team_group not in allowed_teams:

                    allowed_teams.append(
                        team_row.sales_team_group
                    )


        if allowed_teams:

            team_sql_values = ""


            for allowed_team in allowed_teams:

                escaped_team = frappe.db.escape(
                    allowed_team
                )


                if team_sql_values:

                    team_sql_values = (
                        team_sql_values
                        + ", "
                    )


                team_sql_values = (
                    team_sql_values
                    + escaped_team
                )


            condition_parts.append(
                "`tabDelivery Note`.`custom_sales_team_group` IN ("
                + team_sql_values
                + ")"
            )


        # ====================================================
        # 10. FINAL CONDITION
        # ====================================================

        if condition_parts:

            final_conditions = ""


            for condition_part in condition_parts:

                if final_conditions:

                    final_conditions = (
                        final_conditions
                        + " AND "
                    )


                final_conditions = (
                    final_conditions
                    + condition_part
                )


            conditions = final_conditions


        else:

            conditions = "1 = 0"

# Enforce approver separation of duties and hierarchy scope.
# Permission Query scripts protect lists/reports; this validation also protects
# workflow actions when a user opens a Quotation by a direct URL.

current_user = frappe.session.user

if current_user and current_user not in ("Administrator", "Guest") and not doc.is_new():
    previous_state = frappe.db.get_value("Quotation", doc.name, "workflow_state") or ""
    next_state = doc.get("workflow_state") or ""

    approval_states = (
        "For TL Approval",
        "For Supervisor Approval",
        "For Business Owner Approval",
    )

    # A state change out of an approval queue is an approval/rejection action.
    if previous_state in approval_states and previous_state != next_state:
        if current_user == doc.owner:
            frappe.throw("You cannot approve or reject your own Quotation.")

        actor_rows = frappe.get_all(
            "Sales Access Hierarchy",
            filters={"user": current_user, "active": 1},
            fields=["name", "position", "company", "branch", "sales_team_group"],
            limit=2,
        )

        if len(actor_rows) != 1:
            frappe.throw(
                "Approval requires exactly one active Sales Access Hierarchy record for the current user."
            )

        actor = actor_rows[0]
        allowed_companies = []
        allowed_branches = []
        allowed_teams = []

        if actor.company:
            allowed_companies.append(actor.company)
        if actor.branch:
            allowed_branches.append(actor.branch)
        if actor.sales_team_group:
            allowed_teams.append(actor.sales_team_group)

        for row in frappe.get_all(
            "Sales Hierarchy Company Access",
            filters={"parent": actor.name, "parenttype": "Sales Access Hierarchy"},
            fields=["company"],
        ):
            if row.company and row.company not in allowed_companies:
                allowed_companies.append(row.company)

        for row in frappe.get_all(
            "Sales Hierarchy Branch Access",
            filters={"parent": actor.name, "parenttype": "Sales Access Hierarchy"},
            fields=["branch"],
        ):
            if row.branch and row.branch not in allowed_branches:
                allowed_branches.append(row.branch)

        for row in frappe.get_all(
            "Sales Hierarchy Team Access",
            filters={"parent": actor.name, "parenttype": "Sales Access Hierarchy"},
            fields=["sales_team_group"],
        ):
            if row.sales_team_group and row.sales_team_group not in allowed_teams:
                allowed_teams.append(row.sales_team_group)

        quotation_company = doc.get("company") or ""
        quotation_branch = doc.get("custom_branch") or ""
        quotation_team = doc.get("custom_sales_team_group") or ""

        if not allowed_companies or quotation_company not in allowed_companies:
            frappe.throw("You cannot approve this Quotation because it is outside your Company scope.")

        if previous_state == "For TL Approval":
            if actor.position == "Team Leader":
                if not allowed_branches or not allowed_teams:
                    frappe.throw("Your Team Leader Branch and Sales Team scope must be configured before approval.")
                if quotation_branch not in allowed_branches or quotation_team not in allowed_teams:
                    frappe.throw("You can approve only Quotations for your own Branch and Sales Team.")
            elif actor.position not in (
                "Senior Operations Officer",
                "General Manager",
                "Business Owner",
            ):
                frappe.throw("Only the responsible Team Leader or an authorized senior approver may act here.")

        elif previous_state == "For Supervisor Approval":
            if actor.position != "Supervisor":
                frappe.throw("Only the responsible Sales Supervisor may act here.")
            if not allowed_branches or not allowed_teams:
                frappe.throw("Your Supervisor Branch and Sales Team scope must be configured before approval.")
            if quotation_branch not in allowed_branches or quotation_team not in allowed_teams:
                frappe.throw("You can approve only Quotations for your own Branch and Sales Team.")

        elif previous_state == "For Business Owner Approval":
            if actor.position != "Business Owner":
                frappe.throw("Only the Business Owner for this Company may act here.")
